'use strict';
(async()=>{const $=s=>document.querySelector(s),bridge=window.RPG_ACCOUNT_BRIDGE,dialog=$('#account-dialog'),body=$('#account-body'),cfg=window.RPG_ACCOUNT_CONFIG;let account=null,expedition=null,googleReady=false,notice='',busy=false,editingName=false,auto=null;const linkKey='rpg-cloud-owner';const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function summary(payload){if(!payload)return '<p>아직 저장이 없어요.</p>';let value;try{value=RPG_ENGINE.validate(payload,RPG_DATA);}catch{return '<p>읽을 수 없는 저장입니다.</p>';}const heroes=value.heroes.map((h,i)=>({h,i})).filter(({h})=>h.recruited);return `<b>원정대원 ${heroes.length}명</b><ul>${heroes.map(({h,i})=>`<li>${esc(RPG_DATA.characters[i].name)} · Lv.${h.level} · ${esc(RPG_DATA.characters[i].classes[h.cell].name)} · ${h.stage}스테이지</li>`).join('')||'<li>새 원정대</li>'}</ul>`;}
function nameForm(){return `<section class="expedition-create"><span class="eyebrow">YOUR EXPEDITION</span><h3>${expedition?.profile?'원정대 이름 변경':'원정대의 이름을 지어주세요'}</h3><p>랭킹에 표시할 이름이에요. 이메일은 공개하지 않아요.</p><form id="expedition-name-form"><label for="expedition-name">원정대 이름</label><input id="expedition-name" name="name" minlength="2" maxlength="16" autocomplete="off" placeholder="예: 달빛원정대" value="${esc(expedition?.profile?.name||'')}" required ${busy?'disabled':''}><small>한글·영문·숫자·공백·_- · 2~16자</small><button type="submit" ${busy?'disabled':''}>${busy?'저장 중…':'이 이름으로 시작'}</button></form><p class="account-help">기존 캐릭터와 장비는 그대로 유지돼요. 클라우드에 저장한 게임 기록이 원정대 이름으로 랭킹에 표시됩니다.</p>${expedition?.profile?'<button data-cloud="name-cancel">취소</button>':'<button data-cloud="logout">로그아웃하고 게스트로 계속</button>'}</section>`;}
function render(){if(!account){body.innerHTML='<p>계정 연결을 준비하고 있어요.</p>';return;}const user=account.user,profile=expedition?.owner===user?.id?expedition?.profile:null;const title=$('#expedition-title');if(title)title.textContent=profile?.name||'내 원정대';$('#account-open').textContent=user?'계정 관리 ↗':'구글 계정 연결 ↗';const guest=$('#continue-game');if(guest)guest.textContent='게스트로 하기';const start=$('#google-start');if(start)start.textContent='G　구글로 계속하기';body.innerHTML=`${notice?`<p class="account-notice" role="status">${esc(notice)}</p>`:''}${user?(!profile||editingName?nameForm():`<div class="expedition-heading"><span>내 원정대</span><h3>${esc(profile.name)}</h3><button data-cloud="name-edit">이름 변경</button></div><p class="account-email">${esc(user.email||'구글 계정')}으로 로그인했어요.</p><div class="account-compare"><section><h3>이 기기</h3>${summary(bridge.snapshot())}<button data-cloud="upload" ${busy?'disabled':''}>${account.remote?'이 기기 진행을 클라우드에 저장':'현재 원정대를 이 계정에 연결'}</button></section><section><h3>클라우드</h3>${summary(account.remote?.payload)}<small>${account.remote?esc(new Date(account.remote.updated_at).toLocaleString('ko-KR')):'첫 저장을 기다리고 있어요.'}</small><button data-cloud="download" ${busy||!account.remote?'disabled':''}>클라우드 진행으로 이어 하기</button></section></div><p class="account-help">한 번 연결하면 플레이 중 10초마다 자동 저장해요. 다른 기기에서는 구글로 계속하기를 누르세요. 저장이 서로 바뀌면 자동으로 덮어쓰지 않고 다시 확인합니다. 불러오기 전 기기 저장은 복구용으로 보관합니다.</p><div class="account-actions"><button data-cloud="refresh" ${busy?'disabled':''}>최신 저장 확인</button><button data-cloud="ranking">🏆 랭킹 보기</button><button data-cloud="logout" ${busy?'disabled':''}>로그아웃</button></div>`):`<p>구글 계정에 원정대를 저장하고 모바일·PC에서 이어 하세요.</p><button class="google-login" data-cloud="login" ${busy||!googleReady?'disabled':''}>G　구글로 계속하기</button>${googleReady?'':'<p class="account-help">연결 상태를 확인하고 있어요. 게스트로는 바로 시작할 수 있어요.</p>'}<p class="account-help">로그인만으로 현재 진행을 덮어쓰지 않습니다. 로그인 후 두 저장을 비교해서 선택합니다.</p>`}${bridge.hasBackup()?'<button data-cloud="restore">불러오기 전 기기 저장 복구</button>':''}<a class="textbtn" href="rpg-privacy.html" target="_blank" rel="noopener">개인정보 안내 ↗</a>`;document.dispatchEvent(new Event('rpg:account-render'));}
async function open(){bridge.pause(true);if(!dialog.open)dialog.showModal();render();if(account?.user){try{await Promise.all([account.refresh(),expedition.refreshProfile()]);render();}catch(e){notice=e.message;render();}}}
async function finishGoogleStart(){if(account.remote&&localStorage.getItem(linkKey)===account.user.id){try{await account.download();armCloud();}catch(e){notice=e.message;await open();return;}}startGame();}
function armCloud(){localStorage.setItem(linkKey,account.user.id);auto.enable();notice='클라우드 자동 저장 중 · 10초마다 저장해요.';}
function startGame(){sessionStorage.removeItem('rpg-google-start');dialog.close();document.dispatchEvent(new Event('rpg:home'));}
$('#account-open').onclick=open;document.addEventListener('click',e=>{if(e.target.closest('[data-account-open]'))open();});$('#account-close').onclick=()=>dialog.close();dialog.addEventListener('close',()=>bridge.pause(false));
$('#google-start').onclick=async()=>{if(busy)return;sessionStorage.setItem('rpg-google-start','1');if(account?.user){if(expedition?.profile)await finishGoogleStart();else open();}else{await open();if(googleReady)body.querySelector('[data-cloud="login"]')?.click();}};
body.onsubmit=async e=>{if(e.target.id!=='expedition-name-form')return;e.preventDefault();if(busy)return;const name=new FormData(e.target).get('name');busy=true;notice='';render();try{await expedition.setName(name);editingName=false;await expedition.sync();if(sessionStorage.getItem('rpg-google-start'))await finishGoogleStart();else notice='원정대 이름을 저장했어요.';}catch(err){notice=err.message||'이름을 저장하지 못했어요.';}finally{busy=false;render();}};
body.onclick=async e=>{const action=e.target.closest('[data-cloud]')?.dataset.cloud;if(!action||busy)return;if(action==='name-edit'){editingName=true;render();return;}if(action==='name-cancel'){editingName=false;render();return;}if(action==='ranking'){dialog.close();document.dispatchEvent(new Event('rpg:ranking-open'));return;}busy=true;notice='';render();try{if(action==='login')await account.login(new URL('rpg.html',location.href).href);if(action==='upload'){await account.upload(bridge.snapshot());armCloud();notice='클라우드에 저장했어요.';try{await expedition.sync();notice+=' 랭킹도 갱신했어요.';}catch{notice+=' 랭킹은 새로고침으로 다시 갱신할 수 있어요.';}if(sessionStorage.getItem('rpg-google-start'))startGame();}if(action==='download'){await account.download();armCloud();notice='클라우드 진행을 불러왔어요.';if(sessionStorage.getItem('rpg-google-start'))startGame();}if(action==='restore'){auto.stop();localStorage.removeItem(linkKey);await bridge.restore();notice='이전 기기 저장을 복구했어요. 클라우드 저장은 그대로입니다.';}if(action==='refresh'){await account.refresh();await expedition.refreshProfile();await expedition.sync();notice='최신 저장과 랭킹을 확인했어요.';}if(action==='logout'){auto.stop();await account.logout();expedition.profile=null;expedition.owner=null;editingName=false;sessionStorage.removeItem('rpg-google-start');notice='로그아웃했어요. 기기 저장은 유지됩니다.';}}catch(e){notice=e.message||'연결을 확인해 주세요.';}finally{busy=false;render();}};
try{if(!bridge||!cfg||!window.supabase)throw Error('로그인 구성 요소를 불러오지 못했어요.');const client=supabase.createClient(cfg.url,cfg.publishableKey,{auth:{flowType:'pkce',detectSessionInUrl:true,persistSession:true,autoRefreshToken:true,storageKey:'gaetecheon-google-auth'}});account=new RPG_CLOUD_ACCOUNT(client,{validate:p=>RPG_ENGINE.validate(p,RPG_DATA),apply:bridge.apply,checkpoint:bridge.snapshot,change:render,error:e=>{notice=e.message;render();}});expedition=new RPG_RANKING_CORE.Expedition(client,account,p=>RPG_RANKING_CORE.powers(p,RPG_DATA,RPG_ENGINE));auto=new RPG_CLOUD_ACCOUNT.AutoSave(account,{snapshot:bridge.snapshot,saved:()=>{notice='클라우드 자동 저장 완료 · '+new Date().toLocaleTimeString('ko-KR');expedition.sync().catch(()=>{});if(dialog.open)render();},error:e=>{notice=e.code==='SAVE_CONFLICT'?'다른 기기에서 진행했어요. 자동 저장을 멈췄어요. 이어 할 저장을 선택해 주세요.':'연결이 끊겼어요. 기기에 저장하고 클라우드 저장은 다시 시도해요.';render();if(e.code==='SAVE_CONFLICT')open();}});setInterval(()=>auto.flush(),10000);document.addEventListener('visibilitychange',()=>{if(document.hidden)auto.flush();});document.addEventListener('click',e=>{if(e.target.closest('#continue-game')){auto.stop();localStorage.removeItem(linkKey);sessionStorage.removeItem('rpg-google-start');}},true);window.RPG_ACCOUNT_UI={account,client,expedition,auto,open,continue:()=>{if(account.user&&auto.owner!==account.user.id){notice='이어 할 저장을 선택하면 클라우드 자동 저장이 시작돼요.';sessionStorage.setItem('rpg-google-start','1');open();}else document.dispatchEvent(new Event('rpg:start'));}};document.dispatchEvent(new Event('rpg:account-ready'));await account.init();if(account.user){await expedition.refreshProfile();try{await expedition.sync();}catch{notice='랭킹 갱신은 잠시 후 다시 시도해 주세요.';}}const r=await fetch(cfg.url+'/auth/v1/settings',{headers:{apikey:cfg.publishableKey}});if(r.ok)googleReady=(await r.json()).external?.google===true;render();const callback=new URL(location.href).searchParams.has('code')||location.hash.includes('error_description');if(account.user&&!expedition.profile&&(sessionStorage.getItem('rpg-google-start')||callback))open();else if(account.user&&sessionStorage.getItem('rpg-google-start'))await finishGoogleStart();else if(callback){if(!account.user)notice='로그인을 완료하지 못했어요. 다시 시도해 주세요.';open();}}catch(e){notice='계정 연결을 불러오지 못했어요. 기기 저장은 유지됩니다.';if(account)render();else body.textContent=notice;}
})();
